describe('Footer Links Navigation', () => {
    beforeEach(() => {
        cy.visit('https://example.com'); // Replace with the actual URL of the application
    });

    it('should navigate to the About Us page when the About Us link is clicked', () => {
        cy.get('footer').contains('About Us').click();
        cy.url().should('include', '/about-us');
        cy.get('h1').should('contain', 'About Us');
    });

    it('should display an error message when the Contact Us link is clicked and the page is down', () => {
        cy.intercept('GET', '/contact-us', { statusCode: 500 }).as('getContactUs');
        cy.get('footer').contains('Contact Us').click();
        cy.wait('@getContactUs');
        cy.get('.error-message').should('be.visible').and('contain', 'Sorry, we are experiencing technical difficulties.');
    });
});
